 priority=['cafe-first-visit','cafe-morning-ritual','cafe-before-opening','cafe-seasonal-drink','cafe-work-spot']+[t['id'] for t in source['templates'] if not t['id'].startswith('cafe-')]
 by_stem={e['stem']:e for e in entries};canonical=sorted({e['canonical_stem'] for e in entries},key=lambda s:(priority.index(by_stem[s]['template']),next(i for i,e in enumerate(entries) if e['stem']==s)))
 ROOT.mkdir(exist_ok=True);(ROOT/'assets').mkdir(exist_ok=True);(ROOT/'contact-sheets').mkdir(exist_ok=True);(ROOT/'prompts').mkdir(exist_ok=True)
